      { href: '@root/encyclopedia/great-migration.html', title: 'The Great Migration', description: 'Shows how papers like the Chicago Defender helped carry information north.' },
      { href: '@root/generated/pages/black-church.html', title: 'The Black Church', description: 'Another institution that helped Black communities organize, remember, and communicate.' }
